"use client"

import { useState } from "react"
import axios from "axios"
import { X, Plus, Trash2, AlertCircle, Loader2 } from "lucide-react"

export default function CreateCriterionModal({ isOpen, onClose, onCreate }) {
  const [formData, setFormData] = useState({
    name: "",
    cases: [{ description: "", points: 0 }],
  })
  const [error, setError] = useState("")
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Handle input changes for name
  const handleNameChange = (e) => {
    setFormData({ ...formData, name: e.target.value })
  }

  // Handle input changes for cases
  const handleCaseChange = (index, field, value) => {
    const updatedCases = formData.cases.map((c, i) =>
      i === index ? { ...c, [field]: field === "points" ? parseInt(value) || 0 : value } : c
    )
    setFormData({ ...formData, cases: updatedCases })
  }

  // Add a new case
  const addCase = () => {
    setFormData({
      ...formData,
      cases: [...formData.cases, { description: "", points: 0 }],
    })
  }

  // Remove a case
  const removeCase = (index) => {
    if (formData.cases.length === 1) {
      setError("Un critère doit avoir au moins un cas.")
      return
    }
    const updatedCases = formData.cases.filter((_, i) => i !== index)
    setFormData({ ...formData, cases: updatedCases })
  }

  // Handle form submission
  const handleSubmit = async (e) => {
    e.preventDefault()
    setError("")
    setIsSubmitting(true)

    const token = localStorage.getItem("token")
    if (!token) {
      setError("Authentification requise. Veuillez vous connecter.")
      setIsSubmitting(false)
      return
    }

    // Validate form data
    if (!formData.name.trim()) {
      setError("Le nom du critère est requis.")
      setIsSubmitting(false)
      return
    }
    if (formData.cases.some(c => !c.description.trim())) {
      setError("Tous les cas doivent avoir une description.")
      setIsSubmitting(false)
      return
    }

    try {
      const response = await axios.post(
        `${process.env.REACT_APP_API_URL}/api/criteria`,
        formData,
        { headers: { Authorization: `Bearer ${token}` } }
      )
      onCreate(response.data) // Pass new criterion to parent
      onClose() // Close modal
      setFormData({ name: "", cases: [{ description: "", points: 0 }] }) // Reset form
    } catch (error) {
      const errorMsg = error.response?.data?.message || "Échec de la création du critère. Veuillez réessayer."
      setError(errorMsg)
    } finally {
      setIsSubmitting(false)
    }
  }

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
      <div className="bg-white rounded-xl shadow-xl max-w-lg w-full mx-4 max-h-[90vh] overflow-y-auto">
        {/* Header */}
        <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-4 flex justify-between items-center">
          <h2 className="text-lg font-bold">Créer un critère</h2>
          <button
            onClick={onClose}
            className="p-1 hover:bg-white/20 rounded-full"
            aria-label="Fermer"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="p-6">
          {/* Error Message */}
          {error && (
            <div className="mb-4 p-3 bg-red-50 border-l-4 border-red-500 flex items-center gap-2">
              <AlertCircle className="h-4 w-4 text-red-500" />
              <p className="text-sm text-red-700">{error}</p>
            </div>
          )}

          {/* Criterion Name */}
          <div className="mb-4">
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Nom du critère
            </label>
            <input
              type="text"
              value={formData.name}
              onChange={handleNameChange}
              className="w-full px-3 py-2 border border-[#C8A45D/30] rounded-md shadow-sm focus:ring-[#00717F] focus:border-[#00717F] text-sm"
              placeholder="Ex: Critère scolaire"
              required
            />
          </div>

          {/* Cases */}
          <div className="mb-4">
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Cas
            </label>
            {formData.cases.map((caseItem, index) => (
              <div key={index} className="flex items-center gap-3 mb-3">
                <div className="flex-1">
                  <input
                    type="text"
                    value={caseItem.description}
                    onChange={(e) => handleCaseChange(index, "description", e.target.value)}
                    className="w-full px-3 py-2 border border-[#C8A45D/30] rounded-md shadow-sm focus:ring-[#00717F] focus:border-[#00717F] text-sm"
                    placeholder="Description du cas"
                    required
                  />
                </div>
                <div className="w-24">
                  <input
                    type="number"
                    value={caseItem.points}
                    onChange={(e) => handleCaseChange(index, "points", e.target.value)}
                    className="w-full px-3 py-2 border border-[#C8A45D/30] rounded-md shadow-sm focus:ring-[#00717F] focus:border-[#00717F] text-sm"
                    placeholder="Points"
                    required
                  />
                </div>
                <button
                  type="button"
                  onClick={() => removeCase(index)}
                  className="p-2 text-red-600 hover:bg-red-50 rounded-full"
                  aria-label="Supprimer le cas"
                >
                  <Trash2 className="h-4 w-4" />
                </button>
              </div>
            ))}
            <button
              type="button"
              onClick={addCase}
              className="mt-2 flex items-center gap-2 text-[#00717F] hover:bg-[#00717F]/10 rounded-md px-3 py-1.5 text-sm"
            >
              <Plus className="h-4 w-4" />
              Ajouter un cas
            </button>
          </div>

          {/* Actions */}
          <div className="flex justify-end gap-3">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 border border-[#C8A45D/30] text-gray-700 rounded-md hover:bg-gray-50 text-sm"
            >
              Annuler
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="px-4 py-2 bg-[#00717F] text-white rounded-md hover:bg-[#00717F]/90 flex items-center gap-2 text-sm"
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" />
                  Traitement...
                </>
              ) : (
                "Créer"
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}
